<!--vbase-->
<template>
  <template v-if="is_module_on">
    <f-btn
      v-if="is_icon_button"
      id="create_task_btn"
      icon="add_task"
      @click="createTaskPopup = true"
      class="q-mr-sm"
    >
      <q-tooltip>{{ $t('create_task') }}</q-tooltip>
    </f-btn>
    <f-btn
      v-else
      class="q-ml-sm"
      appearance="secondary"
      @click="createTaskPopup = true"
      :label="$t('create_task')"
    >
    </f-btn>
    <q-dialog v-model="createTaskPopup" @hide="createTaskPopup = false">
      <q-card style="width: 700px; max-width: 50vw">
        <Create
          @closeCreatePopup="createTaskPopup = false"
          @refreshTasks="refreshTasks"
        />
      </q-card>
    </q-dialog>
    <Loader />
  </template>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin.js';
import helper from 'src/pages/FieldValidation/helper';
import { objLen } from 'src/utils/general';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import Create from 'src/components/document/Tasks/Create.vue';

import {
  useTaskStore,
  useDropdownStore,
  useGroupDropdownStore,
  useDocumentStore,
} from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [helperUtil, helperMixin, helper],
  props: {
    is_icon_button: {
      type: Boolean,
      default: false,
    },
  },
  components: {
    Loader,
    Create,
  },
  watch: {
    processing: function (val) {
      if (val) {
        this.showLoading();
      } else {
        this.hideLoading();
      }
    },
  },
  data() {
    return {
      docId: '',
      currentDisplayedMessage: ref(''),
    };
  },

  mounted: function () {
    this.init();
    window.addEventListener('resize', this.windowResize);
    document.body.addEventListener('click', this.mouseClicked, true);
  },

  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
  },

  methods: {
    init() {
      this.isModuleOn();
      this.prepareUsersDropdown();
      this.getGroups();
    },

    refreshTasks() {
      notify.success(this.$t('MSG_SAVE'));
      let document_id = '';
      if (this.record && this.record.doc_id) {
        document_id = this.record.doc_id;
      }
      this.getOpenTasks(document_id);
    },
  },
  setup() {
    const task_store = useTaskStore();
    const { task, data_fetched, is_module_on } = storeToRefs(task_store);
    const { getTask, resetTaskStore, isModuleOn, getOpenTasks } = task_store;

    const dropdown_store = useDropdownStore();
    const { prepareUsersDropdown } = dropdown_store;

    const group_dropdown_store = useGroupDropdownStore();
    const { getGroups } = group_dropdown_store;

    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    return {
      getOpenTasks,
      record,
      isModuleOn,
      is_module_on,
      data_fetched,
      prepareUsersDropdown,
      getGroups,
      resetTaskStore,
      task,
      getTask,
      createTaskPopup: ref(false),
    };
  },
});
</script>

